contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Call sequence: owner (this contract) opens to public, then calls donate{value: amount}().
    // We assert that if donate succeeds, winnersPot() (which is address(c).balance/2) does not increase.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // Need some ETH to forward to donate
        require(address(this).balance >= amount);

        // This contract deployed c so it is owner and can open to public
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        // Observe before values
        uint256 beforeWinners = c.winnersPot(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.donate{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterWinners = c.winnersPot(); if (__ESBMC_reverted()) return;

        // General rule: if donate did not revert then winnersPot (balance/2) did not increase
        assert(reverted || afterWinners <= beforeWinners);
    }

    // Allow receiving ETH so the test can forward donations
    receive() external payable {}
}

